output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Customers are obliged to take the available entrance cart before completing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_available_at_entrance": "cartAt(1,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cart_available_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_hand_carried_items",
    "text": "Customers are prohibited from carrying groceries by hand or picking up shelf items unless they are pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "must_return_cart_front_bay",
    "text": "Customers are obliged to return the cart to the front return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "return_cart_front": {
          "pre": {
            "and": [
              "front_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "item_pickup_triggers_cart_return",
    "text": "After taking any item from a shelf, the customer is obliged to return the cart to the front bay before exit.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "item_taken_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": null
        },
        "return_cart_front": {
          "pre": {
            "and": [
              "front_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_taken_with_cart",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "no_cart_abandonment_outside_front",
    "text": "Customers are prohibited from putting down a cart anywhere except the designated front return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_front": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "front_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_front"
    }
  },
  {
    "id": "must_drop_cart_when_at_front",
    "text": "A customer who reaches the front return bay while pushing a cart is prohibited from doing anything other than leaving the cart there.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "proper_front_dropoff": {
          "pre": {
            "and": [
              "front_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "front_return_bay",
          "pushing_cart",
          {
            "not": "LEAVE_CART"
          }
        ]
      }
    }
  },
  {
    "id": "exit_requires_cart_parked",
    "text": "Customers are prohibited from exiting unless they are no longer pushing a cart and the cart is parked at the front return bay.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_parked_front": "cartAt(0,1)",
        "ready_for_cartless_exit": {
          "and": [
            {
              "not": "pushing_cart"
            },
            "cart_parked_front"
          ]
        }
      },
      "events": {
        "cartless_exit": {
          "pre": {
            "and": [
              "EXIT",
              "ready_for_cartless_exit"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "ready_for_cartless_exit"
          }
        ]
      }
    }
  },
  {
    "id": "front_interaction_is_cart_return",
    "text": "Interactions at the front bay are prohibited unless the interaction is specifically leaving the cart there.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "front_cart_return": {
          "pre": {
            "and": [
              "front_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        },
        "front_nonreturn_interaction": {
          "pre": {
            "and": [
              "front_return_bay",
              "INTERACT",
              {
                "not": "LEAVE_CART"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "front_nonreturn_interaction"
    }
  }
]
